def transform(g):
    g=[r[:] for r in g]; h,w=len(g),len(g[0])
    # find horizontal bars: rows with runs of same nonzero color
    bars=[]  # (row,color,gapcols)
    for r,row in enumerate(g):
        c=0
        while c<w:
            if row[c]!=0:
                col=row[c]; s=c
                while c<w and row[c]==col: c+=1
                e=c-1
                if e-s>=2: bars.append((r,col,s,e))
            else: c+=1
    # gap col: the single missing col within span (between first and last cell)
    from collections import defaultdict
    fills=defaultdict(list)  # col -> list of (row,color)
    for r,col,s,e in bars:
        gaps=[x for x in range(s,e+1) if g[r][x]==0]
        if len(gaps)==1:
            fills[gaps[0]].append((r,col))
    for col,lst in fills.items():
        lst.sort(); prev=-1
        for r,color in lst:
            for rr in range(prev+1,r+1): g[rr][col]=color
            prev=r
    return g

